fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Pre-allocate enough space for all elements
    let mut result = Vec::with_capacity(arr.len() + values.len());
    // Move all elements from `arr` into `result`
    result.extend(arr);
    // Move all elements from `values` into `result`
    result.extend(values);
    result
}

